import dataclasses

@dataclasses.dataclass
class TranscriptionRequest:
    audio_file_url: str
    locale: str = "en-US"
    display_name: str = "BatchTranscriptionJob"

@dataclasses.dataclass
class TranscriptionResult:
    id: str
    status: str
    transcript_url: str | None = None
    error_message: str | None = None

import requests
import time
from speech_client import get_batch_transcription_client
from speech_models import TranscriptionResult

def poll_transcription_job(job_url: str) -> TranscriptionResult:
    client_config = get_batch_transcription_client()
    speech_key = client_config["key"]

    headers = {
        "Ocp-Apim-Subscription-Key": speech_key,
    }

    while True:
        try:
            response = requests.get(job_url, headers=headers)
            response.raise_for_status()

            response_data = response.json()
            status = response_data.get("status")
            job_id = response_data.get("id") # The 'id' field should contain the job ID

            if status == "Succeeded":
                # Get the results URL
                files_url = response_data["links"]["files"]
                files_response = requests.get(files_url, headers=headers)
                files_response.raise_for_status()
                files_data = files_response.json()

                transcript_url = None
                for file_entry in files_data["values"]:
                    if file_entry["kind"] == "Transcription":
                        transcript_url = file_entry["links"]["contentUrl"]
                        break

                return TranscriptionResult(
                    id=job_id,
                    status=status,
                    transcript_url=transcript_url
                )
            elif status in ["Failed", "Canceled"]:
                error_message = response_data.get("properties", {}).get("error", {}).get("message")
                return TranscriptionResult(
                    id=job_id,
                    status=status,
                    error_message=error_message or "Transcription job failed or was canceled."
                )
            else:
                print(f"Transcription job {job_id} is in status: {status}. Waiting...")
                time.sleep(30)  # Wait for 30 seconds before polling again

        except requests.exceptions.RequestException as e:
            print(f"Error polling transcription job: {e}")
            return TranscriptionResult(
                id=None,
                status="Failed",
                error_message=str(e)
            )

import requests
import json
from speech_client import get_batch_transcription_client
from speech_models import TranscriptionRequest, TranscriptionResult

def submit_diarization_job(request: TranscriptionRequest) -> TranscriptionResult:
    client_config = get_batch_transcription_client()
    speech_key = client_config["key"]
    service_region = client_config["region"]
    endpoint = client_config["endpoint"]

    transcriptions_url = f"{endpoint}/transcriptions"

    headers = {
        "Ocp-Apim-Subscription-Key": speech_key,
        "Content-Type": "application/json"
    }

    payload = {
        "contentUrls": [
            request.audio_file_url
        ],
        "locale": request.locale,
        "displayName": f"{request.display_name}_Diarized",
        "properties": {
            "wordLevelTimestampsEnabled": True, # Diarization often requires word-level timestamps
            "diarizationEnabled": True,
            "punctuationMode": "DictatedAndAutomatic",
            "profanityFilterMode": "Masked"
        }
    }

    try:
        response = requests.post(transcriptions_url, headers=headers, data=json.dumps(payload))
        response.raise_for_status()  # Raise an exception for HTTP errors

        response_data = response.json()
        job_id = response_data.get("self")
        status = response_data.get("status")

        job_id_extracted = job_id.split('/')[-1] if job_id else None

        return TranscriptionResult(
            id=job_id_extracted,
            status=status,
            transcript_url=job_id # The full URL to poll
        )
    except requests.exceptions.RequestException as e:
        print(f"Error submitting diarization job: {e}")
        return TranscriptionResult(
            id=None,
            status="Failed",
            error_message=str(e)
        )

